#!/bin/bash
# data fork (round G): the ONE guard for arm uog1, on worker-node (/workspace/jev_guards/ops/recipe_g/uog1/uog1_guard.sh; line in loops.ctl.txt).
# usage: uog1_guard.sh   with the node in ./uog1_node.txt = "<workspace id> <tag>" (one line). Generated by vg_genarm.py from uf2's cloud guard (823e25f3). Every ~2 min:
#   1. "finished" comes ONLY from the S3 marker recipe_g/uog1/state/uog1_chain_done (read here, never from the training node's disk) -> exit.
#      A fail marker or 3 failed restages -> stop relaunching, keep watching.
#   2. workspace TERMINATED (spot loss / the 08:05Z pass) -> `ascale start --yes`, only after a marker read that SUCCEEDED and said "not done".
#   3. an alive 8-GPU worker with no uog1 chain on it -> launch uog1_chain.sh from S3 (it restages, checks every checksum, resumes from S3).
#   4. webterminal keepalive about every 30 min. It kills nothing, ever. It keeps no state of its own. A second copy exits at once (flock in start_all.sh too).
unset ASCALE_RUN_ID; cd "$(dirname "$0")" || exit 1; L=uog1_guard.log
if [ -f uog1_guard.pid ] && kill -0 "$(cat uog1_guard.pid)" 2>/dev/null && ps -o command= -p "$(cat uog1_guard.pid)" | grep -q "uog1_guard.sh"; then
  echo "[uog1-guard $(date -u +%FT%TZ)] a guard is already running (pid $(cat uog1_guard.pid)): this copy exits" >> $L; exit 0; fi
echo $$ > uog1_guard.pid
read -r WS TAG < uog1_node.txt; NAME=uog1; [ -n "$WS" ] && [ -n "$TAG" ] || { echo "no uog1_node.txt" >> $L; exit 1; }
U=s3://YOUR_BUCKET/jev-race/engineering/vision/recipe_g/uog1
log(){ echo "[uog1-guard $(date -u +%FT%TZ)] $*" >> $L; }
st(){ ascale status $1 2>/dev/null | awk '$1=="state"{print $2}'; }
worker(){ ascale now $1 2>/dev/null | awk 'NR==1{for(i=1;i<=NF;i++){if($i=="HEAD")h=i; if($i=="STATE")t=i}} $1=="node" && $t=="ALIVE" && $h=="false" {print $3; exit}'; }
marker(){ # -> "MK done=<0|1> fail=<0|1> rf=<n>" from S3, or empty if the read itself failed
  bash -c "export AWS_DEFAULT_REGION=us-east-2; S=\$(aws s3 ls $U/state/ 2>&1); rc=\$?; [ \$rc -le 1 ] && echo \"\$S\" | grep -q -E 'AccessDenied|Could not|error' && rc=9; [ \$rc -le 1 ] && echo \"MK st=\$(echo \"\$S\" | grep -c ' ${NAME}_started\$') done=\$(echo \"\$S\" | grep -c ' ${NAME}_chain_done\$') fail=\$(echo \"\$S\" | grep -c ' ${NAME}_fail\$') rf=\$(aws s3 cp --quiet $U/state/${NAME}_restage_fails - 2>/dev/null | tr -dc 0-9 | cut -c1-3)\"" 2>/dev/null | grep "^MK " | tail -1
}
MX=s3://YOUR_BUCKET/jev-race/engineering/vision/recipe_mx; idle=0
qdone(){ # every job of the merge agent's p12 queue has its done marker
  local q; q=$(aws s3 cp --quiet $MX/queue/p12.txt - 2>/dev/null) || return 1; [ -n "$q" ] || return 1
  echo "$q" | while read -r lab mk rest; do [ "$lab" = "END" ] && continue; [ -z "$mk" ] && continue; aws s3 ls $MX/$mk > /dev/null 2>&1 || exit 1; done
}
mine(){ # p12 is shared with the merge agent: until this arm has started there once (S3 marker), its queue must be finished AND the node idle on two probes in a row
  [ "$TAG" = "p12" ] || return 0
  echo "$M" | grep -q "st=1" && return 0
  qdone || { idle=0; [ $((n % 10)) = 1 ] && log "$TAG: the merge agent's queue is not finished: waiting"; return 1; }
  P=$(ascale run $WS --node $w --backend ws -- "echo \"ID mx=\$(pgrep -fc '[m]x_') tr=\$(pgrep -fc '[q]v_train.py') ev=\$(pgrep -fc '[s]oup_eval') mem=\$(nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits | sort -n | tail -1)\"" 2>/dev/null | grep "^ID " | tail -1)
  case "$P" in "ID mx=0 tr=0 ev=0 mem="*) [ "$(echo "$P" | sed 's/.*mem=//')" -lt 2000 ] 2>/dev/null && idle=$((idle+1)) || idle=0;; *) idle=0;; esac
  log "$TAG queue finished; idle probe: $P (idle rounds $idle of 2)"
  [ $idle -ge 2 ]
}
log "armed pid=$$ ws=$WS tag=$TAG"; n=0; held=0
while :; do
  n=$((n+1))
  M=$(marker)
  if [ -z "$M" ]; then [ $((n % 5)) = 1 ] && log "marker read failed (S3 read failed): doing nothing this round"; sleep 110; continue; fi
  case "$M" in *"done=1"*) log "S3 marker ${NAME}_chain_done exists ($M): exit"; exit 0;; esac
  rf=$(echo "$M" | sed -n 's/.* rf=\([0-9]*\).*/\1/p'); rf=${rf:-0}
  if echo "$M" | grep -q "fail=1" || [ "$rf" -ge 3 ]; then
    [ $held = 0 ] && log "HOLD: $M (smoke fail marker or 3 failed restages): no relaunch, no workspace start until the marker is removed"; held=1
    sleep 110; continue
  fi
  held=0
  s=$(st $WS); w=$(worker $WS)
  if [ "$s" = "TERMINATED" ]; then log "$TAG state TERMINATED, run unfinished ($M) -> start: $(ascale start $WS --yes 2>&1 | tail -1 | cut -c1-120)"; sleep 110; continue; fi
  if [ -z "$w" ]; then [ $((n % 10)) = 1 ] && log "$TAG state $s, no alive worker yet"; sleep 110; continue; fi
  [ $((n % 15)) = 2 ] && ascale run $WS --backend webterminal -- 'echo KEEPALIVE' > /dev/null 2>&1
  O=$(ascale run $WS --node $w --backend ws -- "LG=/data/local/uog1/logs/uog1_chain_$NAME.log; echo \"ST chain=\$(pgrep -fc '[u]og1_chain.sh') gpus=\$(nvidia-smi -L 2>/dev/null | wc -l) :: \$(grep '\\\"event\\\": \\\"step\\\"' /data/local/qv/runs/$NAME/train_log.jsonl 2>/dev/null | tail -1 | grep -o '\\\"step\\\": [0-9]*') :: \$(tail -n 1 \$LG 2>/dev/null | cut -c1-200)\"" 2>/dev/null | grep "^ST " | tail -1)
  if [ -z "$O" ]; then sleep 110; continue; fi
  [ $((n % 5)) = 1 ] && log "$TAG $w $O"
  if echo "$O" | grep -q "gpus=8" && echo "$O" | grep -q "chain=0 "; then
    if ! mine; then sleep 110; continue; fi
    log "$TAG launch chain on $w: $(ascale run $WS --node $w --backend ws --detach --name uog1_chain_$(date -u +%d%H%M%S) -- "export AWS_DEFAULT_REGION=us-east-2; mkdir -p /data/local/uog1/code; aws s3 cp --quiet $U/code/uog1_chain.sh /data/local/uog1/code/uog1_chain.sh && exec bash /data/local/uog1/code/uog1_chain.sh $TAG $NAME" 2>&1 | tail -3 | tr '\n' ' ' | cut -c1-200)"
  fi
  sleep 110
done
